using System;
using System.Collections.Generic;
using System.Drawing;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Reflection;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Json;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace EtiquetaLocal {
 [DataContract] public class UpdateSettings { [DataMember] public string Repository="";[DataMember] public bool AutoCheck; }
 [DataContract] public class ReleaseAsset { [DataMember] public string name;[DataMember] public string browser_download_url;[DataMember] public long size; }
 [DataContract] public class GithubRelease { [DataMember] public string tag_name;[DataMember] public bool draft;[DataMember] public bool prerelease;[DataMember] public ReleaseAsset[] assets; }
 public static class Updates {
  // Cada variante se actualiza con su propio paquete y recuerda su propia versión activa.
#if SENCILLA
  public const string Package="Impresorapp-Sencilla-";const string ActiveName="active-version-sencilla.txt";
#else
  public const string Package="Impresorapp-";const string ActiveName="active-version.txt";
#endif
  public const string VersionText=AppVersion.Text;
  static string ActiveFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"EtiquetaLocal",ActiveName);}}
  public static string ValidateActivePath(string exe){string root=Path.GetFullPath(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"EtiquetaLocal","versions")).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string path=Path.GetFullPath(exe);if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(Path.GetFileName(path),"^"+Regex.Escape(Package)+@"\d+(\.\d+){1,3}\.exe$")||!File.Exists(path))throw new Exception("Ruta de versión activa no válida.");return path;}
  public static void Launch(string exe){string path=ValidateActivePath(exe);Process.Start(new ProcessStartInfo(path){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(path)});try{Directory.CreateDirectory(Path.GetDirectoryName(ActiveFile));DesignStorage.Write(ActiveFile,path);}catch{} }
  public static bool TryRedirect(){try{if(!File.Exists(ActiveFile))return false;string path=ValidateActivePath(File.ReadAllText(ActiveFile).Trim());if(AssemblyName.GetAssemblyName(path).Version<=ParseVersion(VersionText))return false;Process.Start(new ProcessStartInfo(path){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(path)});return true;}catch{return false;}}
  static string SettingsFile {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"EtiquetaLocal","updates.json");}}
  public static string NormalizeRepo(string value){value=(value??"").Trim().TrimEnd('/');if(value.StartsWith("https://github.com/",StringComparison.OrdinalIgnoreCase))value=value.Substring(19);if(value.EndsWith(".git",StringComparison.OrdinalIgnoreCase))value=value.Substring(0,value.Length-4);if(!Regex.IsMatch(value,@"^[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]{1,100}$")||value.Split('/')[1]=="."||value.Split('/')[1]=="..")throw new Exception("Introduce el enlace de GitHub o usuario/repositorio, sin rutas adicionales.");return value;}
  public static Version ParseVersion(string tag){Version v;if(!Version.TryParse((tag??"").TrimStart('v','V'),out v)||v.Major<0)throw new Exception("La versión publicada no es válida.");return new Version(v.Major,v.Minor,Math.Max(0,v.Build),Math.Max(0,v.Revision));}
  public static UpdateSettings Load(){foreach(string path in new[]{SettingsFile,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"update-defaults.json")})try{if(File.Exists(path)){using(var s=File.OpenRead(path)){var cfg=(UpdateSettings)new DataContractJsonSerializer(typeof(UpdateSettings)).ReadObject(s);if(cfg!=null){if(!String.IsNullOrWhiteSpace(cfg.Repository))cfg.Repository=NormalizeRepo(cfg.Repository);return cfg;}}}}catch{}return new UpdateSettings();}
  static void Save(UpdateSettings settings){if(!String.IsNullOrWhiteSpace(settings.Repository))settings.Repository=NormalizeRepo(settings.Repository);else settings.AutoCheck=false;Directory.CreateDirectory(Path.GetDirectoryName(SettingsFile));using(var ms=new MemoryStream()){new DataContractJsonSerializer(typeof(UpdateSettings)).WriteObject(ms,settings);DesignStorage.Write(SettingsFile,Encoding.UTF8.GetString(ms.ToArray()));}}
  public static bool Configure(IWin32Window owner){var settings=Load();using(var f=new Form{Text="Actualizaciones · Impresorapp "+VersionText,ClientSize=new Size(580,290),StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",9),Icon=Branding.AppIcon,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,BackColor=Color.FromArgb(242,247,244)}){
   var info=new System.Windows.Forms.Label{Text="Repositorio de versiones (público):",Left=18,Top=20,Width=540};var repo=new TextBox{Left=18,Top=48,Width=540,Text=settings.Repository};var auto=new CheckBox{Text="Buscar nuevas versiones automáticamente al abrir",Left=18,Top=90,Width=540,Checked=settings.AutoCheck};
   var note=new System.Windows.Forms.Label{Text="Se consulta GitHub Releases. Subir código sin publicar una versión no genera una actualización.\n\nSi hay novedades, podrás descargarlas y abrir la versión nueva tras guardar tu diseño. No se cambian controladores ni firmware. No admite repositorios privados en esta versión.",Left=18,Top=125,Width=540,Height=95};
   var check=Ui.Action("network","Guardar y buscar",()=>{try{settings.Repository=NormalizeRepo(repo.Text);settings.AutoCheck=auto.Checked;Save(settings);f.DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Repositorio");}},180,true);check.Location=new Point(18,235);var save=Ui.Action("save","Guardar ajustes",()=>{try{settings.Repository=repo.Text.Trim();settings.AutoCheck=auto.Checked;Save(settings);f.DialogResult=DialogResult.Cancel;}catch(Exception ex){MessageBox.Show(f,ex.Message,"Ajustes");}},170);save.Location=new Point(210,235);var cancel=new Button{Text="Cerrar",Left=395,Top=237,Width=160,Height=30,DialogResult=DialogResult.Cancel};f.Controls.AddRange(new Control[]{info,repo,auto,note,check,save,cancel});f.CancelButton=cancel;return f.ShowDialog(owner)==DialogResult.OK;
  }}
  static byte[] Fetch(string url,int max){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var req=(HttpWebRequest)WebRequest.Create(url);req.UserAgent="Impresorapp/"+VersionText;req.Accept="application/vnd.github+json";req.Timeout=20000;req.ReadWriteTimeout=20000;using(var response=(HttpWebResponse)req.GetResponse()){if(response.ContentLength>max)throw new Exception("La descarga supera el límite permitido.");using(var input=response.GetResponseStream())using(var output=new MemoryStream()){byte[] buffer=new byte[8192];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(output.Length+n>max)throw new Exception("La descarga supera el límite permitido.");output.Write(buffer,0,n);}return output.ToArray();}}}
  public static GithubRelease ParseRelease(byte[] json){using(var ms=new MemoryStream(json))return (GithubRelease)new DataContractJsonSerializer(typeof(GithubRelease)).ReadObject(ms);}
  public static ReleaseAsset FindAsset(GithubRelease release,string repo,string name){var asset=(release.assets??new ReleaseAsset[0]).SingleOrDefault(a=>a.name==name);if(asset==null)throw new Exception("La publicación no incluye "+name+". Pide al responsable que publique el paquete y su SHA-256.");Uri uri;if(!Uri.TryCreate(asset.browser_download_url,UriKind.Absolute,out uri)||uri.Scheme!="https"||!String.Equals(uri.Host,"github.com",StringComparison.OrdinalIgnoreCase)||!uri.AbsolutePath.StartsWith("/"+repo+"/releases/download/",StringComparison.OrdinalIgnoreCase))throw new Exception("El archivo no pertenece al repositorio configurado.");return asset;}
  public static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  public static void Verify(byte[] bytes,string checksum){string expected=(checksum??"").Trim().Split(new[]{' ','\t','\r','\n'},StringSplitOptions.RemoveEmptyEntries).FirstOrDefault();if(expected==null||!Regex.IsMatch(expected,@"\A[0-9a-fA-F]{64}\z")||!String.Equals(expected,Hash(bytes),StringComparison.OrdinalIgnoreCase))throw new Exception("El paquete no coincide con su comprobación SHA-256. No se abrirá.");}
  public static string Extract(byte[] zip,string destination,string version){Directory.CreateDirectory(destination);string root=Path.GetFullPath(destination).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;long total=0;using(var ms=new MemoryStream(zip))using(var archive=new ZipArchive(ms,ZipArchiveMode.Read)){
   if(archive.Entries.Count>200)throw new Exception("Demasiados archivos en el paquete.");foreach(var entry in archive.Entries){string name=entry.FullName.Replace('/',Path.DirectorySeparatorChar);if(Path.IsPathRooted(name)||name.Contains(":"))throw new Exception("Ruta no válida en la actualización.");string target=Path.GetFullPath(Path.Combine(root,name));if(!target.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("El paquete intenta salir de su carpeta.");if(String.IsNullOrEmpty(entry.Name)){Directory.CreateDirectory(target);continue;}total+=entry.Length;if(total>150000000||entry.Length>80000000)throw new Exception("El paquete extraído supera el límite permitido.");Directory.CreateDirectory(Path.GetDirectoryName(target));using(var input=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write)){byte[] buffer=new byte[8192];int n;long count=0;while((n=input.Read(buffer,0,buffer.Length))>0){count+=n;if(count>entry.Length)throw new Exception("Longitud de archivo no válida.");output.Write(buffer,0,n);}}
   }}
   string[] candidates=Directory.GetFiles(root,Package+version+".exe",SearchOption.AllDirectories);if(candidates.Length!=1)throw new Exception("No se encuentra el ejecutable de esta versión.");string exe=candidates[0],folder=Path.GetDirectoryName(exe);if(!File.Exists(Path.Combine(folder,"QRCoder.dll"))||!File.Exists(exe+".config"))throw new Exception("La actualización está incompleta.");if(AssemblyName.GetAssemblyName(exe).Version!=ParseVersion(version))throw new Exception("La versión del ejecutable no coincide con la publicación.");return exe;
  }
  public static async Task<string> Check(IWin32Window owner,bool automatic){
   var cfg=Load();if(String.IsNullOrWhiteSpace(cfg.Repository)){if(!automatic)MessageBox.Show(owner,"Configura primero el repositorio en Actualizaciones.","Repositorio pendiente");return null;}if(automatic&&!cfg.AutoCheck)return null;
   bool downloading=false;try{var release=await Task.Run(()=>ParseRelease(Fetch("https://api.github.com/repos/"+cfg.Repository+"/releases/latest",2000000)));if(release==null||release.draft||release.prerelease)throw new Exception("No hay una versión estable publicada.");var version=ParseVersion(release.tag_name);if(version<=ParseVersion(VersionText)){if(!automatic)MessageBox.Show(owner,"Ya tienes la versión más reciente publicada.","Impresorapp "+VersionText);return null;}
    string text=release.tag_name.TrimStart('v','V'),name=Package+text+".zip";var package=FindAsset(release,cfg.Repository,name);var sum=FindAsset(release,cfg.Repository,name+".sha256");
    if(MessageBox.Show(owner,"Está disponible Impresorapp "+text+".\n\n¿Descargarla? Después podrás guardar tu diseño y reiniciar en la versión nueva. Tus diseños y preferencias se conservan.","Nueva versión",MessageBoxButtons.YesNo,MessageBoxIcon.Information)!=DialogResult.Yes)return null;
    downloading=true;using(var progress=new Form{Text="Descargando Impresorapp "+text,ClientSize=new Size(420,100),StartPosition=FormStartPosition.CenterParent,ControlBox=false,Font=new Font("Segoe UI",9),Icon=Branding.AppIcon}){progress.Controls.Add(new System.Windows.Forms.Label{Text="Descargando y comprobando el paquete de GitHub…",Left=20,Top=15,Width=380});progress.Controls.Add(new ProgressBar{Style=ProgressBarStyle.Marquee,Left=20,Top=50,Width=380});progress.Show(owner);try{return await Task.Run(()=>{var zip=Fetch(package.browser_download_url,80000000);Verify(zip,Encoding.UTF8.GetString(Fetch(sum.browser_download_url,4096)));string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"EtiquetaLocal","versions",text+"-"+Guid.NewGuid().ToString("N"));return Extract(zip,folder,text);});}finally{progress.Close();}}
   }catch(WebException ex){if(!automatic||downloading)MessageBox.Show(owner,"No se pudo consultar o descargar la versión. Comprueba Internet, el repositorio público y sus Releases.\n"+ex.Message,"Actualizaciones");return null;}catch(Exception ex){if(!automatic||downloading)MessageBox.Show(owner,ex.Message,"No se pudo actualizar");return null;}
  }
  public static void SelfTest(){if(Package!=AppVersion.Name.Replace(" ","-")+"-")throw new Exception("El paquete de actualización no corresponde a esta variante ("+AppVersion.Name+").");if(NormalizeRepo("https://github.com/example/labels.git")!="example/labels"||ParseVersion("v0.17")<=ParseVersion("0.16"))throw new Exception("Versión/repositorio");bool rejected=false;try{NormalizeRepo("https://other.test/example/labels");}catch{rejected=true;}if(!rejected)throw new Exception("Repositorio ajeno");byte[] bytes=Encoding.UTF8.GetBytes("test");Verify(bytes,Hash(bytes)+"  file.zip");rejected=false;try{Verify(bytes,new string('0',64));}catch{rejected=true;}if(!rejected)throw new Exception("Integridad de actualización");
   var release=ParseRelease(Encoding.UTF8.GetBytes("{\"tag_name\":\"v0.17\",\"draft\":false,\"prerelease\":false,\"assets\":[{\"name\":\"p.zip\",\"browser_download_url\":\"https://github.com/example/labels/releases/download/v0.17/p.zip\"}]}"));FindAsset(release,"example/labels","p.zip");rejected=false;try{FindAsset(release,"example/other","p.zip");}catch{rejected=true;}if(!rejected)throw new Exception("Origen de paquete");
   string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"update-test-"+Guid.NewGuid().ToString("N"));try{using(var ms=new MemoryStream()){using(var z=new ZipArchive(ms,ZipArchiveMode.Create,true)){using(var w=new StreamWriter(z.CreateEntry("../escape.txt").Open()))w.Write("bad");}rejected=false;try{Extract(ms.ToArray(),root,"0.17");}catch{rejected=true;}if(!rejected||File.Exists(Path.Combine(Path.GetDirectoryName(root),"escape.txt")))throw new Exception("Extracción insegura");}}finally{if(Directory.Exists(root))Directory.Delete(root,true);}
  }
 }
}
